function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");
}

function block(name, idx) {
  const lines = ROWS.map((r) => `  "${r[0]}": "${esc(r[idx])}",`);
  return `const ${name}: Record<string, string> = {\n${lines.join("\n")}\n};`;
}

const header = `import type { AppLocale } from "./types";

`;

const footer = `
export const SECONDARY_MARKET_MESSAGES: Record<AppLocale, Record<string, string>> = {
  ru: RU,
  en: EN,
  es: ES,
  pt: PT,
};
`;

const content = header + [block("RU", 1), block("EN", 2), block("ES", 3), block("PT", 4)].join("\n\n") + footer;
fs.writeFileSync(outPath, content, "utf8");
console.log(`Wrote ${ROWS.length} keys to ${outPath}`);
